<?php
namespace App\Http\Controllers;use App\Jobs\{ExecuteBiometricDeletion,RunEventFaceIndex};use App\Models\{BiometricDeletionRequest,BiometricReport,EventFaceIndexRun,FaceMatchResult,FaceSearchSubject,Group};use Illuminate\Http\Request;use Illuminate\Support\Facades\{Gate};use Illuminate\Support\Str;
class BiometricComplianceController extends Controller{public function myPhotos(Request$r,FaceSearchSubject$s){abort_unless($s->user_id===$r->user()->id,403);$photos=$s->results()->whereIn('review_state',['accepted','confirmed','unreviewed'])->with('asset.photo.group')->get()->filter(function($m)use($r){$p=$m->asset?->photo;return$p&&$m->asset->state==='completed'&&Gate::forUser($r->user())->allows('view',$p);})->map(fn($m)=>['match_id'=>$m->id,'photo_id'=>$m->asset->photo_id,'url'=>$m->asset->photo->url,'similarity'=>(float)$m->similarity])->values();return response()->json(['photos'=>$photos]);}public function reject(Request$r,FaceMatchResult$m){abort_unless($m->faceSearchSubject->user_id===$r->user()->id,403);$m->update(['review_state'=>'rejected','rejected_at'=>now()]);BiometricReport::firstOrCreate(['face_match_result_id'=>$m->id,'reporter_id'=>$r->user()->id],['uuid'=>(string)Str::uuid(),'reason'=>'not_me','state'=>'pending']);return response()->json(['state'=>'rejected']);}public function review(Request$r,FaceMatchResult$m){Gate::authorize('manageMembers',$m->asset->group);$data=$r->validate(['decision'=>'required|in:confirmed,rejected','note'=>'nullable|string|max:500']);$m->update(['review_state'=>$data['decision'],'reviewed_by'=>$r->user()->id,'review_note'=>$data['note']??null,'reviewed_at'=>now(),'rejected_at'=>$data['decision']==='rejected'?now():null]);return response()->json(['state'=>$data['decision']]);}public function deletion(Request$r){$data=$r->validate(['group_id'=>'nullable|integer|exists:groups,id','scope'=>'required|in:event,account']);if($data['scope']==='event'){abort_unless(isset($data['group_id']),422);$g=Group::findOrFail($data['group_id']);abort_unless($g->isMember($r->user()),403);}$d=BiometricDeletionRequest::create(['uuid'=>(string)Str::uuid(),'group_id'=>$data['group_id']??null,'user_id'=>$r->user()->id,'scope'=>$data['scope'],'state'=>'queued','requested_at'=>now()]);ExecuteBiometricDeletion::dispatch($d->id);return response()->json(['uuid'=>$d->uuid,'state'=>'queued'],202);}public function deletionStatus(Request$r,BiometricDeletionRequest$d){abort_unless($d->user_id===$r->user()->id||$r->user()->isAdmin(),403);return response()->json($d);}public function startIndex(Request$r,Group$g){Gate::authorize('update',$g);$run=EventFaceIndexRun::create(['uuid'=>(string)Str::uuid(),'group_id'=>$g->id,'requested_by'=>$r->user()->id,'state'=>'queued','total'=>$g->photos()->whereHas('mediaAsset')->count()]);RunEventFaceIndex::dispatch($run->id);return response()->json(['uuid'=>$run->uuid,'state'=>'queued'],202);}public function indexStatus(Request$r,EventFaceIndexRun$run){$g=Group::findOrFail($run->group_id);Gate::authorize('update',$g);return response()->json($run);}}
